```json
{"action": "sql", "sql": "SELECT t1.name FROM products AS t1 JOIN order_items AS t2 ON t1.product_id = t2.product_id JOIN orders AS t3 ON t2.order_id = t3.order_id WHERE t3.status != 'cancelled' GROUP BY t1.product_id ORDER BY SUM(t2.quantity * t2.unit_price) DESC LIMIT 3", "reason": "Вычислить выручку для каждого товара, исключая отменённые заказы, и отсортировать товары по убыванию выручки, вернув топ-3."}
```

```json
{"action": "sql", "sql": "SELECT c.name FROM categories c JOIN products p ON c.category_id = p.category_id WHERE p.price IS NOT NULL GROUP BY c.category_id ORDER BY SUM(oi.quantity * oi.unit_price) DESC LIMIT 1", "reason": "Определяем категорию с наибольшей выручкой, исключая отменённые заказы."}
```

```json
{"action": "sql", "sql": "SELECT name FROM customers WHERE customer_id NOT IN (SELECT customer_id FROM orders)", "reason": "Найти клиентов, у которых нет заказов в таблице orders."}
```

```json
{"action": "sql", "sql": "SELECT c.city FROM customers c JOIN orders o ON c.customer_id = o.customer_id WHERE o.status != 'cancelled' GROUP BY c.city ORDER BY SUM(oi.quantity * oi.unit_price) DESC LIMIT 1", "reason": "Чтобы определить город клиента с наибольшей выручкой, необходимо объединить таблицы customers и orders, отфильтровать отменённые заказы, вычислить выручку для каждого заказа и затем сгруппировать по городу, отсортировать и выбрать город с наибольшей выручкой."}
```

```json
{"action": "sql", "sql": "SELECT sum(oi.quantity) FROM order_items oi JOIN products p ON oi.product_id = p.product_id WHERE p.name = \"Наушники Pro ANC\" AND oi.order_id IN (SELECT order_id FROM orders WHERE status != \"cancelled\")", "reason": "Вычисляем общее количество проданных наушников Pro ANC, исключая отмененные заказы."}
```

```json
{"action": "sql", "sql": "SELECT c.name, SUM(oi.quantity * oi.unit_price) AS total_spent FROM customers c JOIN orders o ON c.customer_id = o.customer_id WHERE o.status != 'cancelled' GROUP BY c.customer_id ORDER BY total_spent DESC LIMIT 1", "reason": "Нужно найти клиента с наибольшей суммой потраченных денег, исключая отменённые заказы."}
```

```json
